// Get the input date from n8n context
const inputDate = $input.first().json['Readable date'];

// Handle the specific format "November 8th 2025, 3:02:34 am"
// Remove the ordinal suffixes (st, nd, rd, th) from the day
const cleanedDate = inputDate.replace(/(\d+)(st|nd|rd|th)/, '$1');

// Convert the cleaned date
const date = new Date(cleanedDate);
const year = date.getFullYear();
const month = String(date.getMonth() + 1).padStart(2, '0');
const day = String(date.getDate()).padStart(2, '0');
const formattedDate = `${year}-${month}-${day}`;

// Return as array of objects for n8n
return [{ 
    json: {
        formattedDate: formattedDate
    }
}];
